import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatExceptionOfType;

import org.junit.jupiter.api.Test;

public class PhoneNumberExtraTest {

    private void expectFailure(String input, String message) {
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> new PhoneNumber(input))
                .withMessage(message);
    }

    @Test
    public void cleansAllFormats() {
        assertThat(new PhoneNumber("+1 (613)-995-0253").getNumber()).isEqualTo("6139950253");
        assertThat(new PhoneNumber("613-995-0253").getNumber()).isEqualTo("6139950253");
        assertThat(new PhoneNumber("1 613 995 0253").getNumber()).isEqualTo("6139950253");
        assertThat(new PhoneNumber("613.995.0253").getNumber()).isEqualTo("6139950253");
        assertThat(new PhoneNumber("223 456   7890   ").getNumber()).isEqualTo("2234567890");
        assertThat(new PhoneNumber("12234567890").getNumber()).isEqualTo("2234567890");
        assertThat(new PhoneNumber("+1 (223) 456-7890").getNumber()).isEqualTo("2234567890");
    }

    @Test
    public void rejectsInvalid() {
        expectFailure("123456789", "must not be fewer than 10 digits");
        expectFailure("22234567890", "11 digits must start with 1");
        expectFailure("321234567890", "must not be greater than 11 digits");
        expectFailure("523-abc-7890", "letters not permitted");
        expectFailure("523-@:!-7890", "punctuations not permitted");
        expectFailure("(023) 456-7890", "area code cannot start with zero");
        expectFailure("(123) 456-7890", "area code cannot start with one");
        expectFailure("(223) 056-7890", "exchange code cannot start with zero");
        expectFailure("(223) 156-7890", "exchange code cannot start with one");
        expectFailure("1 (023) 456-7890", "area code cannot start with zero");
        expectFailure("1 (123) 456-7890", "area code cannot start with one");
        expectFailure("1 (223) 056-7890", "exchange code cannot start with zero");
        expectFailure("1 (223) 156-7890", "exchange code cannot start with one");
        expectFailure("+0 613 995 0253", "11 digits must start with 1");
        expectFailure("", "must not be fewer than 10 digits");
    }
}
